mapper.select:
select t1.id id , t1.maintain_plan_id maintainPlanId
     , t3.name_cn stackName
     , core_temp_max_early_time coreTempMaxEarlyTime
     , core_temp_all_early_time coreTempAllEarlyTime
     , oxygen_max_early_time oxygenMaxEarlyTime
     , oxygen_all_early_time oxygenAllEarlyTime
     , temp_max_early_time tempMaxEarlyTime
     , temp_all_early_time tempAllEarlyTime
     , humitidy_max_early_time humidityMaxEarlyTime
     , humitidy_all_early_time humidityAllEarlyTime
     , maintain_result maintainResult
from tb_maintain_early_time t1 , tb_maintain_plan t2 ,tb_stack t3

    t1.maintain_plan_id = t2.id and t2.stack_id = t3.id
    and pid_route like concat('%',concat(#{maintainEarlyTimeDto.siteRoute},'%'))
    and t3.id = #{maintainEarlyTimeDto.siteId}
    and core_temp_all_early_time >= #{maintainEarlyTimeDto.coreTempAllEarlyTimeOne}
    and core_temp_all_early_time <= #{maintainEarlyTimeDto.coreTempAllEarlyTimeTwo}
    and core_temp_max_early_time >= #{maintainEarlyTimeDto.coreTempMaxEarlyTimeOne}
    and core_temp_max_early_time <= #{maintainEarlyTimeDto.coreTempMaxEarlyTimeTwo}
    and temp_all_early_time >= #{maintainEarlyTimeDto.tempAllEarlyTimeOne}
    and temp_all_early_time <= #{maintainEarlyTimeDto.tempAllEarlyTimeTwo}
    and temp_max_early_time >= #{maintainEarlyTimeDto.tempMaxEarlyTimeOne}
    and temp_max_early_time <= #{maintainEarlyTimeDto.tempMaxEarlyTimeTwo}
    and oxygen_all_early_time >= #{maintainEarlyTimeDto.oxygenAllEarlyTimeOne}
    and oxygen_all_early_time <= #{maintainEarlyTimeDto.oxygenAllEarlyTimeTwo}
    and oxygen_max_early_time >= #{maintainEarlyTimeDto.oxygenMaxEarlyTimeOne}
    and oxygen_max_early_time <= #{maintainEarlyTimeDto.oxygenMaxEarlyTimeTwo}
    and humidity_all_early_time >= #{maintainEarlyTimeDto.humidityAllEarlyTimeOne}
    and humidity_all_early_time <= #{maintainEarlyTimeDto.humidityAllEarlyTimeTwo}
    and humidity_max_early_time >= #{maintainEarlyTimeDto.humidityMaxEarlyTimeOne}
    and humidity_max_early_time <= #{maintainEarlyTimeDto.humidityMaxEarlyTimeTwo}
    and maintain_result = #{maintainEarlyTimeDto.maintainResult}
